// Forth evaluates a small subset of Forth given as lines of input.
// It returns the final contents of the stack, or an error if any
// word fails (empty stack, divide by zero, undefined word, ...).
func Forth(input []string) ([]int, error) {
	stack := []int{}
	words := map[string][]string{}

	for _, line := range input {
		queue := strings.Fields(line)
		for len(queue) > 0 {
			tok := queue[0]
			queue = queue[1:]

			if tok == ":" {
				// A definition must be: : name body... ;
				if len(queue) < 2 || queue[1] != ";" {
					return nil, errors.New("invalid definition")
				}
				name := strings.ToLower(queue[0])
				if isNumber(name) {
					return nil, errors.New("cannot redefine a number")
				}
				words[name] = append([]string(nil), queue[:len(queue)-1]...)
				queue = nil
				continue
			}

			if n, err := strconv.Atoi(tok); err == nil {
				stack = append(stack, n)
				continue
			}

			name := strings.ToLower(tok)
			if body, ok := words[name]; ok {
				// Execute the body, resolving names when it runs.
				queue = append(append([]string(nil), body...), queue...)
				continue
			}

			switch name {
			case "+", "-", "*":
				if len(stack) < 2 {
					return nil, errors.New("not enough values on the stack")
				}
				top := stack[len(stack)-1]
				second := stack[len(stack)-2]
				stack = stack[:len(stack)-2]
				switch name {
				case "+":
					stack = append(stack, second+top)
				case "-":
					stack = append(stack, second-top)
				case "*":
					stack = append(stack, second*top)
				}
			case "/":
				if len(stack) < 2 {
					return nil, errors.New("not enough values on the stack")
				}
				top := stack[len(stack)-1]
				second := stack[len(stack)-2]
				stack = stack[:len(stack)-2]
				if top == 0 {
					return nil, errors.New("divide by zero")
				}
				stack = append(stack, second/top)
			case "dup":
				if len(stack) == 0 {
					return nil, errors.New("empty stack")
				}
				stack = append(stack, stack[len(stack)-1])
			case "drop":
				if len(stack) == 0 {
					return nil, errors.New("empty stack")
				}
				stack = stack[:len(stack)-1]
			case "swap":
				if len(stack) < 2 {
					return nil, errors.New("not enough values on the stack")
				}
				stack[len(stack)-1], stack[len(stack)-2] = stack[len(stack)-2], stack[len(stack)-1]
			case "over":
				if len(stack) < 2 {
					return nil, errors.New("not enough values on the stack")
				}
				stack = append(stack, stack[len(stack)-2])
			default:
				return nil, errors.New("undefined operation")
			}
		}
	}

	return stack, nil
}

// isNumber reports whether s is a (possibly negative) integer literal.
func isNumber(s string) bool {
	_, err := strconv.Atoi(s)
	return err == nil
}

